import json
from urban_micro import (
    budget_frontier,
    frontier_rank_attribution,
    frontier_rank_trajectory,
)


def intervention_sig_report():
    # One interval; all three kinds reject, all lower bounds positive so
    # every kind is robust. Items ordered by rank (reject first, then
    # descending mean, then kind): green(0.9), roof(0.5), material(0.1).
    def item(kind, mean, rank):
        return (
            '{"kind":"%s","n":2,"mean":%.6f,"se":0.010000,"lower":%.6f,'
            '"upper":%.6f,"p":0.001000,"q":0.003000,"reject":true,"rank":%d}'
            % (kind, mean, mean - 0.1, mean + 0.1, rank)
        )

    def group(by, key, factor):
        items = ",".join(
            item(kind, mean * factor, rank)
            for kind, mean, rank in (
                ("green", 0.9, 1), ("roof", 0.5, 2), ("material", 0.1, 3)
            )
        )
        return '{"by":"%s","key":"%s","items":[%s]}' % (by, key, items)

    groups = ",".join(
        [group("region", "north", 1.0), group("window", "east", 1.0)]
    )
    interval = (
        '{"start":0.000000,"end":100.000000,"groups":[%s]}' % groups
    )
    return '{"alpha":0.050000,"intervals":[%s]}\n' % interval


sig = intervention_sig_report()
budgets = [0, 10, 20, 30, 40]

