# Synthetic canonical report: two picks with equal support, panel ranks
# alternate so pick "p"'s driver alternates region/window across four
# steps; rejected at every later point.
def rank_entry(pick, rank, support, effect, panels, driver, stable):
    panel_str = ",".join(
        '{"by":"%s","key":"%s","effect":%.6f,"rank":%d,"delta":%d,'
        '"direction":"%s","contribution":%.6f}'
        % (by, key, peff, prank, prank - rank,
           "rise" if prank - rank < 0
           else "fall" if prank - rank > 0 else "same",
           peff - effect)
        for by, key, peff, prank in panels
    )
    return (
        '{"pick":%s,"n":2,"support":%.6f,"effect":%.6f,"rank":%d,'
        '"stable":%s,"driver":{"by":"%s","key":"%s"},"panels":[%s]}'
        % (json.dumps([pick]), support, effect, rank,
           "true" if stable else "false", driver[0], driver[1], panel_str)
    )


